<template><section class="protocol-directory" aria-label="协议大全"><p>收录 {{protocols.length}} 个常见协议／标准条目。层次采用实用分类；TLS、路由控制等不强行等同于单一 OSI 层。端口为常见约定，可被配置改变；协议号、以太网类型与端口不是一回事。</p><input v-model="query" type="search" aria-label="搜索协议" placeholder="搜索 TCP / DHCP / 443 / 加密 / 路由" /><nav class="protocol-filters" aria-label="协议用途分类"><button v-for="name in categories" :key="name" type="button" :aria-pressed="category===name" @click="category=name"><ToolEntryIcon name="导航" />{{name||'全部协议'}}</button></nav><label class="protocol-layer">层次筛选<select v-model="layer" aria-label="协议层次"><option value="">全部层次</option><option v-for="name in layers" :key="name">{{name}}</option></select></label><p>{{filtered.length}} 条结果</p><div class="protocol-grid"><article v-for="entry in pageEntries" :key="entry.id" class="protocol-card"><header><ToolEntryIcon name="导航" /><h3>{{entry.name}}</h3></header><small>{{entry.category}} · {{entry.layer}}</small><p>{{entry.description}}</p><dl><dt>常见端口／标识</dt><dd>{{entry.ports}}</dd><dt>承载方式</dt><dd>{{entry.transport}}</dd></dl><a :href="entry.source" target="_blank" rel="noopener noreferrer">标准／官方资料 ↗</a></article></div><p v-if="!filtered.length">没有匹配的协议。<button type="button" @click="reset">清除筛选</button></p><nav v-if="pages>1" class="protocol-pages" aria-label="协议分页"><button type="button" :disabled="page===1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button type="button" :disabled="page===pages" @click="page++">下一页</button></nav><p><a href="https://www.iana.org/assignments/service-names-port-numbers/service-names-port-numbers.xhtml" target="_blank" rel="noopener noreferrer">IANA 服务与端口注册表 ↗</a></p></section></template>
<script>
import ToolEntryIcon from './ToolEntryIcon.vue';
import {protocols,filterProtocols} from '../data/protocols.mjs';
export default {name:'ProtocolDirectory',components:{ToolEntryIcon},data:()=>({protocols,query:'',category:'',layer:'',page:1,pageSize:18}),computed:{categories(){return ['',...new Set(protocols.map(p=>p.category))];},layers(){return [...new Set(protocols.map(p=>p.layer))];},filtered(){return filterProtocols(this);},pages(){return Math.max(1,Math.ceil(this.filtered.length/this.pageSize));},pageEntries(){return this.filtered.slice((this.page-1)*this.pageSize,this.page*this.pageSize);}},watch:{query(){this.page=1;},category(){this.page=1;},layer(){this.page=1;}},methods:{reset(){this.query='';this.category='';this.layer='';this.page=1;}}};
</script>
<style scoped>.protocol-directory{font-size:13px;line-height:1.8;}p,small,dt{color:var(--el-text-color-secondary);}button,input,select{font:inherit;padding:8px 10px;border:1px solid var(--el-border-color);color:inherit;background:var(--el-fill-color-blank);max-width:100%;box-sizing:border-box;}button{cursor:pointer;}button:disabled{opacity:.4;cursor:default;}input{width:100%;}.protocol-filters,.protocol-pages{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0;}.protocol-layer{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}.protocol-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;}.protocol-card{min-width:0;padding:16px;border:1px solid var(--el-border-color-light);background:var(--el-fill-color-blank);border-radius:3px;overflow-wrap:anywhere;}.protocol-card header{display:flex;align-items:center;gap:3px;}h3{margin:0;font-size:16px;}dl{margin:12px 0;}dd{margin:2px 0 10px;}a{color:var(--ui-accent);}.protocol-pages{justify-content:center;}@media(max-width:1100px){.protocol-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}@media(max-width:600px){.protocol-grid{grid-template-columns:minmax(0,1fr);}}</style>
